#version 300 es
precision highp float;
precision highp int;
precision highp sampler2D;

uniform sampler2D u_image;
uniform int operation;
uniform float factor;
uniform float mean;
uniform float standard_deviation;

out vec4 fragColor;

void main() {
    vec4 x = texelFetch(u_image, ivec2(gl_FragCoord.xy), 0);
    if (operation == 0) {
        fragColor = 1.0 - x;
    } else if (operation == 1) {
        fragColor = (x - mean) / standard_deviation;
    } else if (operation == 2) {
        fragColor = clamp(x * factor, 0.0, 1.0);
    } else {
        fragColor = clamp((x - 0.5) * factor + 0.5, 0.0, 1.0);
    }
}

#version 300 es
precision highp float;
precision highp int;
precision highp sampler2D;

uniform sampler2D u_image;
uniform int operation;
uniform int radius;
uniform float sigma;
uniform float strength;

out vec4 fragColor;

const int MAX_RADIUS = 31;

float weights[2 * MAX_RADIUS + 1];

void loadKernel() {
    float total = 0.0;
    for (int offset = -radius; offset <= radius; offset++) {
        float c = float(offset) / float(radius);
        float weight = exp(-(c * c) / (2.0 * sigma * sigma));
        weights[offset + radius] = weight;
        total += weight;
    }
    for (int i = 0; i <= 2 * radius; i++) {
        weights[i] /= total;
    }
}

int reflectIndex(int position, int size) {
    if (size == 1) {
        return 0;
    }
    int period = 2 * (size - 1);
    int wrapped = abs(position) % period;
    return wrapped < size ? wrapped : period - wrapped;
}

vec4 gaussianBlur(ivec2 center, ivec2 size) {
    if (radius == 0) {
        return texelFetch(u_image, center, 0);
    }
    loadKernel();
    vec4 accumulated = vec4(0.0);
    for (int dy = -radius; dy <= radius; dy++) {
        int y = reflectIndex(center.y + dy, size.y);
        vec4 row = vec4(0.0);
        for (int dx = -radius; dx <= radius; dx++) {
            int x = reflectIndex(center.x + dx, size.x);
            row += weights[dx + radius] * texelFetch(u_image, ivec2(x, y), 0);
        }
        accumulated += weights[dy + radius] * row;
    }
    return accumulated;
}

void main() {
    ivec2 center = ivec2(gl_FragCoord.xy);
    ivec2 size = textureSize(u_image, 0);
    if (operation == 0) {
        fragColor = gaussianBlur(center, size);
    } else {
        vec4 x = texelFetch(u_image, center, 0);
        fragColor = clamp(x + 10.0 * strength * (x - gaussianBlur(center, size)), 0.0, 1.0);
    }
}

